// AssertDirectivesContractAcrossImpls runs [AssertDirectivesContract] once per named factory under
// `t.Run(Name, ...)`. New impls drop in via slice append. The
// variadic `opts` apply to every factory's contract run.
func AssertDirectivesContractAcrossImpls(t *testing.T, factories []DirectivesNamedFactory, opts ...suite.Option) {
	t.Helper()
	for _, nf := range factories {
		t.Run(nf.Name, func(t *testing.T) {
			t.Parallel()
			AssertDirectivesContract(t, nf.Factory, opts...)
		})
	}
}
